package notification.core.template;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import notification.core.NotificationType;import notification.core.template.Template;import notification.core.template.TemplateProvider;import java.util.Map;import java.util.Optional;import java.util.concurrent.ConcurrentHashMap;/** * Decorates any TemplateProvider with an in-memory cache. * TODO: swap ConcurrentHashMap for Caffeine when eviction/TTL matter. */@Slf4j@RequiredArgsConstructorpublic class CachedTemplateProvider implements TemplateProvider {    private final TemplateProvider delegate;    private final Map<String, Template> cache = new ConcurrentHashMap<>();    @Override    public Optional<Template> find(NotificationType type, String language, String version, String variant) {        String key = type + ":" + language + ":" + version + ":" + variant;        Template cached = cache.get(key);        if (cached != null) return Optional.of(cached);        Optional<Template> loaded = delegate.find(type, language, version, variant);        loaded.ifPresent(t -> cache.put(key, t));        return loaded;    }}